// Files for using the identity on the web: CSS variables, design tokens, a React component, a
// landing-page starter, the favicon and app icon, and the kit's own offline index.html.

import { lockup, mark } from './artwork.js'
import { colour as resolveColour, colourName, fill, logoOptions, paintOptions } from './brand.js'
import { escape, n6 } from './format.js'

const webSvg = ({ brand }, width, height, art, title) => `<svg xmlns="http://www.w3.org/2000/svg" width="${n6(width)}" height="${n6(height)}" viewBox="0 0 ${n6(width)} ${n6(height)}" role="img" aria-label="${escape(title)}"><title>${escape(title)}</title>`
  + `<desc>${escape(fill(brand, brand.web?.svgDescription ?? brand.copy?.svgDescription ?? '{name} identity.'))}</desc>${art}</svg>\n`

const prefix = (brand) => brand.web?.cssPrefix ?? brand.id

/** The square app icon: the symbol, centred on the brand colour. */
export const appIconSvg = (ctx) => {
  const { brand } = ctx
  const spec = brand.web?.appIcon ?? {}
  const [, , sw, sh] = brand.symbol.viewBox
  const scale = (spec.size ?? 760) / sw
  const art = `<rect width="1024" height="1024" fill="${resolveColour(brand, spec.background ?? 'primary')}"/>`
    + `<g transform="translate(${n6((1024 - sw * scale) / 2)} ${n6((1024 - sh * scale) / 2)}) scale(${n6(scale)})">${mark(ctx, resolveColour(brand, spec.colour ?? 'reverse'))}</g>`
  return webSvg(ctx, 1024, 1024, art, `${brand.name} app icon`)
}

/** The favicon: the micro symbol in currentColor, switching colour with the system theme. */
export const faviconSvg = (ctx) => {
  const { brand } = ctx
  const spec = brand.web?.favicon ?? {}
  const [, , sw, sh] = brand.symbol.viewBox
  const scale = (spec.size ?? 56) / sw
  const style = `<style>svg{color:${spec.light ?? '#000000'}}@media(prefers-color-scheme:dark){svg{color:${spec.dark ?? '#FFFFFF'}}}</style>`
  const art = style + `<g transform="translate(${n6((64 - sw * scale) / 2)} ${n6((64 - sh * scale) / 2)}) scale(${n6(scale)})">${mark(ctx, 'currentColor', spec.micro !== false)}</g>`
  return webSvg(ctx, 64, 64, art, fill(brand, spec.title ?? '{name} favicon'))
}

const fontFaces = (brand, base = '../') => {
  const seen = new Set()
  return Object.values(brand.fonts ?? {}).filter((face) => face.web && !seen.has(face.web) && seen.add(face.web)).map((face) => {
    const format = face.web.endsWith('.woff2') ? 'woff2' : face.web.endsWith('.woff') ? 'woff' : face.web.endsWith('.otf') ? 'opentype' : 'truetype'
    const family = /\s/.test(face.family) ? `"${face.family}"` : face.family
    return `@font-face { font-family: ${family}; src: url('${base}${face.web}') format('${format}'); font-style: ${face.style ?? 'normal'}; font-weight: ${face.weight ?? 400}; font-display: swap; }`
  }).join('\n')
}

const stack = (brand, key, fallback) => {
  const face = brand.fonts?.[key]
  if (!face) return fallback
  return face.stack.split(',').map((part) => part.trim()).map((part) => (/\s/.test(part) && !/^".*"$/.test(part) ? `"${part}"` : part)).join(', ')
}

export const brandCss = ({ brand }) => {
  const p = prefix(brand)
  const display = brand.typography?.headlines ?? {}
  const labels = brand.typography?.labels ?? {}
  return `/* ${brand.name} v${brand.displayVersion ?? brand.version}. Generated by brandkit from brand.json.
   Included fonts load locally. Logos use outlined lettering and do not depend on installed fonts. */
${fontFaces(brand)}
:root {
${Object.entries(brand.colours).map(([key, value]) => `  --${p}-${key}: ${value};`).join('\n')}
  --${p}-font-body: ${stack(brand, 'body', 'system-ui, sans-serif')};
  --${p}-font-display: ${stack(brand, 'display', 'system-ui, sans-serif')};
  --${p}-font-label: ${stack(brand, 'label', 'ui-monospace, monospace')};
  --${p}-space-1: 4px; --${p}-space-2: 8px; --${p}-space-3: 12px;
  --${p}-space-4: 16px; --${p}-space-6: 24px; --${p}-space-8: 32px;
  --${p}-space-12: 48px; --${p}-space-16: 64px; --${p}-space-24: 96px;
}
.${p}-display { font-family: var(--${p}-font-display); font-weight: ${display.weight ?? 500}; letter-spacing: ${display.trackingEm ?? 0}em; line-height: 1.06; font-size: clamp(2.5rem, 7vw, 5rem); }
.${p}-body { font-family: var(--${p}-font-body); font-size: 1rem; line-height: 1.5; }
.${p}-label { font-family: var(--${p}-font-label); font-size: .75rem; line-height: 1.4; letter-spacing: ${labels.trackingEm ?? 0.12}em; text-transform: uppercase; }
.${p}-logo { display: block; max-width: 100%; height: auto; }
/* Only inline SVG inherits currentColor. SVG loaded through <img> does not. */
`
}

export const tokens = ({ brand }) => ({
  version: brand.version,
  colour: Object.fromEntries(Object.entries(brand.colours).map(([key, value]) => [key, { value, type: 'color' }])),
  roles: Object.fromEntries(Object.keys(brand.roles ?? {}).map((role) => [role, resolveColour(brand, role)])),
  font: { body: brand.fonts?.body?.family, display: brand.fonts?.display?.family, label: brand.fonts?.label?.family },
  typeScale: {
    display: { size: 72, lineHeight: 80, weight: brand.typography?.headlines?.weight ?? 500, tracking: `${brand.typography?.headlines?.trackingEm ?? 0}em` },
    h1: { size: 48, lineHeight: 56, weight: 500 },
    h2: { size: 32, lineHeight: 40, weight: 500 },
    body: { size: 16, lineHeight: 24, weight: 400 },
    caption: { size: 12, lineHeight: 16, weight: 400 },
    label: { size: 12, lineHeight: 16, weight: 400, tracking: `${brand.typography?.labels?.trackingEm ?? 0.12}em` }
  },
  spacing: [4, 8, 12, 16, 24, 32, 48, 64, 96],
  symbol: brand.symbol,
  lockup: brand.lockup,
  wordmark: { construction: brand.web?.wordmarkConstruction ?? 'Outlined lettering', fontIndependent: true }
})

const jsx = (art) => {
  let out = art.replace(/\s+id="[^"]*"/g, '')
  for (const [from, to] of [['fill-rule=', 'fillRule='], ['clip-rule=', 'clipRule='], ['stroke-width=', 'strokeWidth='], ['stroke-linecap=', 'strokeLinecap='], ['stroke-linejoin=', 'strokeLinejoin='], ['class=', 'className=']]) {
    out = out.split(from).join(to)
  }
  return out
}

/** A typed React component with every family and layout inlined, drawn in currentColor. */
export const reactComponent = (ctx) => {
  const { brand } = ctx
  const name = brand.web?.componentName ?? 'BrandLogo'
  const symbolName = brand.web?.symbolComponentName ?? 'BrandSymbol'
  // A fixed-wordmark brand has families in three layouts; a signature brand has one "family" whose
  // layouts are its signatures, all drawn in currentColor.
  const signed = !brand.families?.length
  const families = signed ? ['signature'] : brand.families.map((entry) => entry.id)
  const layouts = signed ? brand.signatures.map((entry) => entry.id) : ['horizontal', 'stacked', 'wordmark']
  const union = (values) => values.map((value) => `'${value}'`).join(' | ')
  const entries = families.map((familyId) => {
    const rows = layouts.map((layout) => {
      const { width, height, art } = signed ? lockup(ctx, { signature: layout, colour: 'currentColor' }) : lockup(ctx, { family: familyId, layout, colour: 'currentColor' })
      return `    '${layout}': { viewBox: '0 0 ${n6(width)} ${n6(height)}', label: '${signed ? brand.name : familyId}', defaultWidth: 240, shape: (<g>${jsx(art)}</g>) },`
    })
    return `  '${familyId}': {\n${rows.join('\n')}\n  },`
  })
  const [, , sw, sh] = brand.symbol.viewBox
  return `import * as React from 'react';

/** Generated by brandkit from brand.json. React 18+ is required for useId().
 * All lettering is outlined; no fonts needed. Set color through CSS or style.
 */
type LogoSvgProps = Omit<React.SVGProps<SVGSVGElement>, 'children' | 'title' | 'viewBox' | 'role'> & {
  title?: string;
  decorative?: boolean;
};
export type ${name}Props = LogoSvgProps & {
  family?: ${union(families)};
  layout?: ${union(layouts)};
};
export type ${symbolName}Props = LogoSvgProps;
type Artwork = { viewBox: string; label: string; defaultWidth: number; shape: React.ReactNode };

const ARTWORK: Record<${union(families)}, Record<${union(layouts)}, Artwork>> = {
${entries.join('\n')}
};
const SYMBOL: Artwork = { viewBox: '0 0 ${n6(sw)} ${n6(sh)}', label: '${brand.name} symbol', defaultWidth: 64, shape: (<g>${jsx(mark(ctx, 'currentColor'))}</g>) };

function SvgArtwork({
  artwork, title, decorative = false, width, height, style,
  'aria-label': ariaLabel, 'aria-labelledby': ariaLabelledBy, ...props
}: LogoSvgProps & { artwork: Artwork }) {
  const titleId = React.useId();
  const accessibleTitle = title ?? artwork.label;
  return (
    <svg {...props}
      xmlns="http://www.w3.org/2000/svg"
      viewBox={artwork.viewBox}
      width={width ?? (height == null ? artwork.defaultWidth : undefined)}
      height={height}
      style={{ display: 'block', maxWidth: '100%', ...(height == null ? { height: 'auto' } : {}), ...style }}
      role={decorative ? undefined : 'img'}
      aria-hidden={decorative ? true : undefined}
      aria-label={decorative ? undefined : ariaLabel}
      aria-labelledby={decorative || ariaLabel ? undefined : (ariaLabelledBy ?? titleId)}
      focusable="false"
    >
      {!decorative && <title id={titleId}>{accessibleTitle}</title>}
      {artwork.shape}
    </svg>
  );
}

export function ${name}({ family = '${families[0]}', layout = '${layouts[0]}', ...props }: ${name}Props) {
  return <SvgArtwork {...props} artwork={ARTWORK[family][layout]} />;
}

export function ${symbolName}(props: ${symbolName}Props) {
  return <SvgArtwork {...props} artwork={SYMBOL} />;
}

export default ${name};
`
}

const lines = (text) => escape(text).split('\n').join('<br>')

/** A one-page website starter in the brand's type, colour and logo. */
export const landingHtml = ({ brand }) => {
  const p = prefix(brand)
  const copy = brand.web?.landing ?? {}
  const primary = `${logoOptions(brand)[0].key}-${paintOptions(brand)[0].id}`
  return `<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="application-version" content="${escape(brand.version ?? '')}"><title>${escape(brand.name)} — landing template</title><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="brand.css">
<style>
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--${p}-${brand.roles?.paper ?? 'paper'});color:var(--${p}-${brand.roles?.ink ?? 'ink'});font-family:var(--${p}-font-body);line-height:1.6}a{color:inherit;text-underline-offset:.25em}.wrap{max-width:1360px;margin:0 auto;padding:0 56px}header{min-height:110px;display:flex;align-items:center;justify-content:space-between;gap:30px;border-bottom:1px solid #b9bdbf}header img{width:236px;height:auto}header a{font-size:.9rem}main{padding:90px 0 0}.hero{display:grid;grid-template-columns:1.15fr 1fr;gap:64px;align-items:center}.hero h1{margin:22px 0 26px;font-size:clamp(3.2rem,6.4vw,6rem);line-height:1.01;font-weight:500;letter-spacing:-.05em;font-family:var(--${p}-font-display)}.hero p{max-width:530px}.hero-art{min-height:510px;background:var(--${p}-${brand.roles?.light ?? 'light'});display:flex;align-items:center;justify-content:center;padding:65px}.hero-art img{display:block;width:100%;height:auto}.button{display:inline-block;background:var(--${p}-${brand.roles?.ink ?? 'ink'});color:white;text-decoration:none;padding:13px 22px;margin-top:24px}.contact{padding:70px 0 76px;margin-top:90px;border-top:1px solid #b9bdbf}.contact h2{font-family:var(--${p}-font-display);font-size:clamp(2rem,4vw,3rem);line-height:1.1;font-weight:500;letter-spacing:-.04em;margin:16px 0 24px}footer{padding:24px 0 44px;border-top:1px solid #b9bdbf;font-size:.8rem}@media(max-width:700px){.wrap{padding:0 24px}.hero{grid-template-columns:1fr;gap:36px}.hero h1{font-size:3.7rem}.hero-art{min-height:330px;padding:54px}}
</style></head>
<body><div class="wrap"><header><img src="../logos/outlined/${primary}.svg" alt="${escape(brand.name)}"><a href="#contact">${escape(copy.cta ?? 'Get in touch')}</a></header><main><section class="hero"><div><p class="${p}-label">${escape(copy.eyebrow ?? '')}</p><h1>${lines(copy.headline ?? brand.name)}</h1><p>${escape(copy.body ?? '')}</p><a class="button" href="#contact">${escape(copy.cta ?? 'Get in touch')}</a></div><div class="hero-art" aria-hidden="true"><img src="../symbol/${brand.id}-symbol-${brand.roles?.primary ?? 'black'}.svg" alt=""></div></section><section id="contact" class="contact"><p class="${p}-label">${escape(copy.contactEyebrow ?? '')}</p><h2>${escape(copy.cta ?? 'Get in touch')}</h2><p>${escape(copy.contactBody ?? '')}</p></section></main><footer>${escape(copy.footer ?? brand.name)}</footer></div></body></html>
`
}

export const formatBytes = (size) => (size < 1024 ? `${size} B` : size < 1024 * 1024 ? `${Math.round(size / 1024)} KB` : `${(size / (1024 * 1024)).toFixed(1)} MB`)

/**
 * The kit's front page: a logo previewer and a searchable list of every file, working from the
 * unzipped folder with no server.
 * @param {Array<{path: string, group: string, bytes: number}>} records
 */
export const indexHtml = ({ brand }, records) => {
  const p = prefix(brand)
  const intro = brand.web?.intro ?? {}
  const has = new Set(records.map((record) => record.path))
  const logos = logoOptions(brand)
  const paints = paintOptions(brand).filter((paint) => paint.raster)
  const ink = paints[0]?.id ?? 'black'
  const reverse = paints.find((paint) => paint.id === 'white' || paint.id === 'reverse' || paint.id === (brand.roles?.reverse ?? 'white'))?.id ?? 'white'
  const families = brand.families?.length ? brand.families : [{ id: logos[0].key }]
  const first = families[0].id
  const gallery = [
    ...logos.slice(0, 6).map((logo, index) => [index === 0 ? `Primary ${logo.label}` : logo.label, `logos/outlined/${logo.key}-${ink}.svg`, logo.layout === 'stacked' ? 'compact' : '']),
    ['Symbol', `symbol/${brand.id}-symbol-${brand.rasterColours?.[0] ?? brand.logoColours?.[0] ?? 'black'}.svg`, 'symbol-card'],
    ['Reversed', `logos/outlined/${logos[0].key}-${reverse}.svg`, 'reverse']
  ].filter(([, path]) => has.has(path))
    .map(([label, path, classes]) => `<a class="logo-card ${classes}" href="${path}" download><div class="logo-card-art"><img src="${path}" alt="${escape(label)}" loading="lazy"></div><div class="card-label">${escape(label)}<span>SVG ↓</span></div></a>`).join('')
  const applications = (brand.templates ?? []).slice(0, 6).filter((template) => has.has(`templates/${template.id}.svg`)).map((template) => {
    const preview = has.has(`templates/png/${template.id}.png`) ? `templates/png/${template.id}.png` : `templates/${template.id}.svg`
    return `<a class="application" href="templates/${template.id}.svg" download><div class="application-art"><img src="${preview}" alt="${escape(template.label ?? template.id)} template" loading="lazy"></div><span>${escape(template.label ?? template.id)}<span>SVG ↓</span></span></a>`
  }).join('')
  const palette = Object.entries(brand.colours).map(([key, value]) => `<div class="swatch"><div style="background:${value}"></div><strong>${escape(colourName(brand, key))}</strong><code>${value}</code></div>`).join('')
  const groups = [...new Set(records.map((record) => record.group))]
  const sections = groups.map((group) => {
    const rows = records.filter((record) => record.group === group).map((record) => {
      const format = record.path.split('.').pop().toUpperCase()
      return `<tr data-asset data-family="${escape(group)}" data-format="${format}" data-search="${escape(`${record.path} ${group}`.toLowerCase())}"><td><a href="${escape(record.path)}" download>${escape(record.path.split('/').pop())}</a><span class="file-path">${escape(record.path)}</span></td><td><span class="file-format">${format}</span></td><td class="file-size">${formatBytes(record.bytes)}</td></tr>`
    })
    return `<details class="asset-family" data-family-group="${escape(group)}"${group === 'Logos' ? ' open' : ''}><summary>${escape(group)} <span class="family-count">${rows.length}</span></summary><table><thead><tr><th scope="col">File / download</th><th scope="col">Format</th><th scope="col" class="file-size">Size</th></tr></thead><tbody>${rows.join('')}</tbody></table></details>`
  }).join('')
  const resources = [['guidelines/' + brand.id + '-brand-guide.pdf', 'Brand guide'], ['logos/' + brand.id + '-logo-sheets.pdf', 'Logo sheets'], ['README.md', 'Read me'], ['source/brand.json', 'brand.json']]
    .filter(([path]) => has.has(path)).map(([path, label]) => `<a class="text-link" href="${path}">${label} <span aria-hidden="true">↗</span></a>`).join('')
  const options = (values) => values.map((value) => `<option value="${escape(value)}">${escape(value)}</option>`).join('')
  const colours = (brand.rasterColours ?? ['black']).map((key) => `<option value="${key}">${escape(colourName(brand, key))}</option>`).join('')
  const backgrounds = [['reverse', 'white'], ['paper', 'paper'], ['primary', 'primary'], ['light', 'light']].map(([role]) => resolveColour(brand, role))
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escape(brand.name)} — Brand kit v${escape(brand.displayVersion ?? brand.version ?? '')}</title>
<link rel="icon" href="web/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="web/brand.css">
<style>
*{box-sizing:border-box}body{margin:0;background:${resolveColour(brand, 'paper')};color:${resolveColour(brand, 'ink')};font-family:var(--${p}-font-body);line-height:1.5}a{color:inherit;text-underline-offset:.2em}img{max-width:100%;height:auto}h1,h2,h3,p{margin:0}h1,h2,h3{font-family:var(--${p}-font-display);font-weight:500;letter-spacing:-.04em}h2{font-size:clamp(1.9rem,3.4vw,2.8rem);line-height:1.15}.wrap{max-width:1328px;margin:0 auto;padding:0 48px}.topbar{min-height:98px;display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:1px solid #d1d1cc}.topbar img{width:148px}.topbar nav{display:flex;gap:28px;font-size:.875rem}.intro{padding:64px 0 38px;display:grid;grid-template-columns:1.2fr 1fr;gap:48px;align-items:end}.intro h1{font-size:clamp(3rem,6.6vw,5.25rem);line-height:1.02;margin-top:20px}.intro-copy>p{color:${resolveColour(brand, 'muted')};font-size:1.05rem;line-height:1.65}.resources{display:flex;flex-wrap:wrap;gap:12px 24px;margin-top:22px}.text-link{font-size:.875rem;text-decoration:none;border-bottom:1px solid;padding-bottom:3px}.preview{border:1px solid #c5c7c7;background:#fff}.stage{height:320px;display:flex;align-items:center;justify-content:center;padding:52px 64px}.stage img{width:100%;max-width:980px;max-height:216px;object-fit:contain}.toolbar{display:flex;flex-wrap:wrap;gap:16px;padding:22px 28px;border-top:1px solid #c5c7c7;align-items:end}.field{display:flex;flex-direction:column;gap:6px}.field>span{font-size:.7rem;letter-spacing:.1em;text-transform:uppercase;font-family:var(--${p}-font-label)}select,input{font:inherit;background:#fff;border:1px solid #a4a8a8;min-height:42px;padding:8px 10px}.section{padding:64px 0;border-bottom:1px solid #d1d1cc}.section h2{margin-bottom:24px}.logo-grid,.applications{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.logo-card,.application{display:block;border:1px solid #d1d1cc;background:#fff;text-decoration:none}.logo-card-art{height:180px;display:flex;align-items:center;justify-content:center;padding:28px}.logo-card-art img{max-height:105px}.logo-card.reverse{background:${resolveColour(brand, 'primary')};color:#fff}.card-label,.application>span{border-top:1px solid #d1d1cc;padding:14px 16px;font-size:.825rem;display:flex;justify-content:space-between}.application-art{height:220px;padding:20px;display:flex;align-items:center;justify-content:center;background:#e8e7e3}.application-art img{max-height:180px;object-fit:contain}.palette{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:12px}.swatch>div{height:86px;border:1px solid #c4c8cb;margin-bottom:12px}.swatch strong{display:block;font-size:.8rem}.swatch code{font-size:.72rem}.catalog-toolbar{display:grid;grid-template-columns:1fr 210px 150px;gap:16px;padding:0 0 24px}.asset-family{border-top:1px solid #bfc4c8}.asset-family summary{padding:20px 0;font-size:1.1rem;cursor:pointer}.family-count{float:right;font-size:.75rem}.asset-family table{width:100%;border-collapse:collapse;margin-bottom:24px;background:#fff}.asset-family td,.asset-family th{padding:10px 16px;border-bottom:1px solid #e3e5e5;text-align:left;font-size:.85rem;overflow-wrap:anywhere}.file-path{display:block;font-size:.7rem;opacity:.7}[hidden]{display:none!important}.footer{padding:30px 0 50px;font-size:.78rem}
@media(max-width:760px){.wrap{padding:0 20px}.intro{grid-template-columns:1fr}.logo-grid,.applications{grid-template-columns:1fr 1fr}.catalog-toolbar{grid-template-columns:1fr}}
</style>
</head>
<body><div class="wrap">
<header class="topbar"><img src="logos/outlined/${brand.families?.length ? `${first}-wordmark` : logos[0].key}-${ink}.svg" alt="${escape(brand.name)}"><span class="${p}-label">${escape(fill(brand, intro.edition ?? 'v{displayVersion}'))}</span><nav><a href="#logos">Logos</a><a href="#catalog">All assets</a></nav></header>
<main>
<section class="intro"><div><p class="${p}-label">${escape(intro.eyebrow ?? 'Brand identity')}</p><h1>${lines(intro.headline ?? `${brand.name}\nBrand assets.`)}</h1></div><div class="intro-copy"><p>${escape(intro.body ?? '')}</p><div class="resources">${resources}</div></div></section>
<section aria-label="Logo preview"><div class="preview"><div class="stage" id="stage"><img id="preview" alt=""></div><div class="toolbar">
<label class="field"${brand.families?.length ? '' : ' hidden'}><span>Name</span><select id="family">${options(families.map((entry) => entry.id))}</select></label>
<label class="field"><span>Layout</span><select id="layout">${brand.families?.length ? options(['horizontal', 'stacked', 'wordmark', 'symbol']) : logos.map((logo) => `<option value="${logo.key}">${escape(logo.label)}</option>`).join('') + '<option value="symbol">Symbol</option>'}</select></label>
<label class="field"><span>Colour</span><select id="colour">${brand.families?.length ? colours : paints.map((paint) => `<option value="${paint.id}">${escape(paint.label)}</option>`).join('')}</select></label>
<label class="field"><span>Background</span><select id="background">${backgrounds.map((value) => `<option>${value}</option>`).join('')}</select></label>
<a class="text-link" id="download" download>Download SVG ↓</a></div></div></section>
<section id="logos" class="section"><h2>The logo system</h2><div class="logo-grid">${gallery}</div></section>
<section class="section"><h2>Colour</h2><div class="palette">${palette}</div></section>
${applications ? `<section class="section"><h2>Applications</h2><div class="applications">${applications}</div></section>` : ''}
<section id="catalog" class="section"><h2>Every file</h2><div class="catalog-toolbar"><label class="field"><span>Search</span><input id="search" type="search" autocomplete="off"></label><label class="field"><span>Group</span><select id="group"><option value="">All</option>${options(groups)}</select></label><label class="field"><span>Format</span><select id="format"><option value="">All</option>${options([...new Set(records.map((record) => record.path.split('.').pop().toUpperCase()))].sort())}</select></label></div><p id="count">${records.length} files</p><div id="assets">${sections}</div></section>
</main>
<footer class="footer">${lines(intro.footer ?? brand.name)}<br>Generated by brandkit from source/brand.json.</footer>
</div>
<script>
(() => {
  const $ = (id) => document.getElementById(id)
  const update = () => {
    const symbol = $('layout').value === 'symbol'
    const file = symbol ? 'symbol/${brand.id}-symbol-' + ${brand.families?.length ? "$('colour').value" : `'${brand.rasterColours?.[0] ?? brand.logoColours?.[0] ?? 'black'}'`} + '.svg' : 'logos/outlined/' + ${brand.families?.length ? "$('family').value + '-' + " : ''}$('layout').value + '-' + $('colour').value + '.svg'
    $('preview').src = file; $('download').href = file; $('stage').style.background = $('background').value
  }
  ;['family', 'layout', 'colour', 'background'].forEach((id) => $(id).addEventListener('change', update)); update()
  const rows = [...document.querySelectorAll('[data-asset]')]
  const filter = () => {
    const words = $('search').value.toLowerCase().split(/\\s+/).filter(Boolean)
    let visible = 0
    rows.forEach((row) => { const ok = (!$('group').value || row.dataset.family === $('group').value) && (!$('format').value || row.dataset.format === $('format').value) && words.every((w) => row.dataset.search.includes(w)); row.hidden = !ok; if (ok) visible++ })
    document.querySelectorAll('[data-family-group]').forEach((g) => { const c = [...g.querySelectorAll('[data-asset]')].filter((r) => !r.hidden).length; g.hidden = !c; g.querySelector('.family-count').textContent = c; if (words.length && c) g.open = true })
    $('count').textContent = visible + ' of ' + rows.length + ' files'
  }
  ;['search', 'group', 'format'].forEach((id) => $(id).addEventListener('input', filter))
})()
</script>
</body></html>
`
}

/** COLOURS.json and a GIMP palette, from the brand's colours. */
export const coloursJson = ({ brand }) => ({
  space: 'sRGB',
  colours: Object.entries(brand.colours).map(([name, hex]) => {
    const value = parseInt(hex.slice(1), 16)
    return { name, hex, rgb: [(value >> 16) & 255, (value >> 8) & 255, value & 255] }
  }),
  pantone: brand.print?.pantone ?? null,
  cmyk: brand.print?.cmyk ?? null,
  printNote: brand.print?.note ?? 'No spot-colour or press-profile match is certified.'
})

export const gimpPalette = ({ brand }) => {
  const rows = coloursJson({ brand }).colours.map(({ name, rgb }) => `${rgb.map((v) => String(v).padStart(3)).join(' ')} ${name}`)
  return `GIMP Palette\nName: ${brand.name}\nColumns: ${rows.length}\n# Normalized sRGB\n${rows.join('\n')}\n`
}
